              const esc = t => String(t ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
              const who = info.uid ? `${esc(info.name || 'Your account')} [${esc(info.uid)}]` : 'Your account';
